public class Main {
    public static void main(String[] args) {
        java.util.List<Integer> ages = java.util.List.of(12, 20, 15);
        int adults = 0;
        for (int age : ages) if (age >= 18) adults++;
        java.util.Map<String, Integer> seen = new java.util.HashMap<>();
        for (String word : new String[]{"cat", "cat", "dog"}) {
            seen.put(word, seen.getOrDefault(word, 0) + 1);
        }
        System.out.println(adults);
        System.out.println(seen.get("cat"));
    }
}

